L001102	\subsection[Extrapolation of Delta-phi]{Extrapolation of $\Delta_{\phi}$}
L001103	\label{sec:delta_phi}
L001104	
L001105	
L001106	
L001107	Replacing $\epsilon^n$ with $\delta^n/n!$, we obtain the Borel transform of the truncated $\Delta_{\phi}(\epsilon)$ series~\eqref{eq:Delta_phi}:
L001108	\begin{align}
L001109	    \calB[\Delta_{\phi}](\delta)\ =\ \left(1-\frac{1}{N_f^2}\right)\left[\delta-\frac{\delta^2}{4}
L001110	    +\frac{\delta^3}{12}\right]+\calO\left(\delta^4\right) \,.
L001111	\end{align}
L001112	If $\Delta_{\phi}(\epsilon)$ is indeed alternating, we would expect $\calB[\Delta_{\phi}](\delta)$ to have a leading singularity on the negative real axis, and the Borel integral might be free of imaginary ambiguities.
L001113	The near-diagonal Pad\'e approximants up to order $\delta^3$ are
L001114	\begin{subequations}
L001115	\begin{align}
L001116	    \calB[\Delta_{\phi}](\delta)\big|_{[1/1]} &=
L001117	    \left(1-\frac{1}{N_f^2}\right)
L001118	    \frac{\delta}{1+\frac{1}{4}\delta}\,,\\
L001119	    \calB[\Delta_{\phi}](\delta)\big|_{[2/1]} &=
L001120	    \left(1-\frac{1}{N_f^2}\right)
L001121	    \frac{\delta + \frac{1}{12}\delta^2}{1+\frac{1}{3}\delta}\,,\\
L001122	    \calB[\Delta_{\phi}](\delta)\big|_{[1/2]} &=
L001123	    \left(1-\frac{1}{N_f^2}\right)
L001124	    \frac{\delta}{1+\frac{1}{4}\delta-\frac{1}{48}\delta^2}\,.
L001125	\end{align}
L001126	\end{subequations}
L001127	The $[1/1]$ and $[2/1]$ Pad\'e approximants have no singularities on the positive real axis, while the $[1/2]$ Pad\'e approximant has a pole at $\delta\approx 15.2 \gg 0$.
L001128	We then obtain the $[m/n]$ PB-resummed function $\Delta_{\phi}(\epsilon)$ by performing the Borel integral,
L001129	\begin{align}
L001130	    \Delta_{\phi}(\epsilon)\big|_{[m/n]} =  \frac{1}{\epsilon}  \int_0^{\infty} d \delta\, e^{-\delta/\epsilon}\, \calB[\Delta_{\phi}](\delta)\big|_{[m/n]}\,.
L001131	\end{align}
L001132	We show the functions $\Delta_{\phi}(\epsilon)|_{[m/n]}\big/\bigl(1-\frac{1}{N_f^2}\bigr)$ in Fig.~\ref{fig:Pade_Borel_phi}.
L001133	The solid lines show the real parts while the shadow bands indicate the imaginary ambiguities, which only appear for $[1/2]$ and are essentially invisible.  (The imaginary ambiguities only become appreciable for $\epsilon \gtrsim 2$.)
L001134	We summarize the results at $\epsilon=1$ in Table~\ref{tab:Pade_sums_phi}.
L001135	We take the union of the envelopes of $\Delta_{\phi}(1)|_{[1/1]}$, $\Delta_{\phi}(1)|_{[2/1]}$, and $\Delta_{\phi}(1)|_{[2/1]}$ as our final estimates of 3D $\Delta_{\phi}$, as we summarize in Table~\ref{tab:Pade_sums_phi'}.
L001136	We would need more terms beyond the three-loop order in the $(2+\epsilon)$D expansion to get more accurate results.
